// Raises every pod target's IPHONEOS_DEPLOYMENT_TARGET to the app's own floor.
//
// Xcode 27 turned "deployment target below the supported range" from a warning
// into a hard error, and three resource-bundle targets still declare ancient
// floors (SDWebImage 9.0, RNSVGFilters 12.4, RNCAsyncStorage 13.4). The app
// itself already targets 15.1, so lifting the pods to match changes nothing
// about which devices can install it.
//
// A config plugin rather than a Podfile edit because ios/ is generated by
// prebuild and gitignored — a hand edit would vanish on the next prebuild.
const { withPodfile } = require('expo/config-plugins');

const FLOOR = '15.1';
const MARKER = '# withPodDeploymentTargetFloor';

const SNIPPET = `
    ${MARKER}
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new('${FLOOR}')
          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${FLOOR}'
        end
      end
    end
`;

module.exports = function withPodDeploymentTargetFloor(config) {
  return withPodfile(config, (cfg) => {
    const podfile = cfg.modResults.contents;
    if (podfile.includes(MARKER)) return cfg;

    // Append at the end of post_install, after react_native_post_install, so
    // nothing that runs later can lower the value again.
    const block = /(post_install do \|installer\|\n[\s\S]*?\n)(  end\n)/;
    if (!block.test(podfile)) {
      throw new Error('withPodDeploymentTargetFloor: no post_install block found in Podfile');
    }
    cfg.modResults.contents = podfile.replace(block, (_, body, end) => body + SNIPPET + end);
    return cfg;
  });
};
